"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["76268"],{77069(e){e.exports=JSON.parse('{"id":"FIN-329","slug":"excise-tax","term":"Excise Tax","also_known_as":[],"difficulty":"Intermediate","definition":"An excise tax is a tax charged on specific goods or activities, such as fuel, alcohol, tobacco or gambling, usually as a fixed amount per unit or a percentage of the price.","explanation":["Unlike general sales taxes or value-added tax, which apply to most goods, excise taxes target particular products. They are often charged at the production or import stage and included in the final price.","Excise taxes serve two main purposes. They raise revenue, and they discourage consumption of products that cause harm to health or the environment, such as cigarettes, sugary drinks or carbon-intensive fuels. In this second role, they help address negative externalities.","For example, if a government charges an excise tax of 0.60 per litre of petrol, that amount is built into the pump price. If petrol costs 1.20 per litre before tax, the price paid by drivers may rise to around 1.80, depending on how the burden is shared.","Because demand for products like fuel and tobacco is often inelastic in the short term, excise taxes can raise reliable revenue. Critics point out that they can take a larger share of income from poorer households, which spend a higher proportion of their income on such goods."],"note":"","total":1725,"prev":{"slug":"exchange-traded-note","term":"Exchange-Traded Note"},"next":{"slug":"exclusion-insurance","term":"Exclusion (Insurance)"}}')}}]);